//! Brave Search LLM Context WASM Tool for IronClaw.//!//! Fetches pre-extracted web content from the Brave Search LLM Context API,//! optimized for grounding LLM responses (RAG, fact-checking, research).//!//! # Authentication//!//! Uses the same Brave Search API key as the Web Search tool://! `ironclaw secret set brave_api_key <key>`//!//! Get a key at: https://brave.com/search/api/wit_bindgen::generate!({    world: "sandboxed-tool",    path: "../../wit/tool.wit",});use serde::Deserialize;// Brave LLM Context API endpoint documentation:// https://api-dashboard.search.brave.com/documentation/services/llm-context//// This tool uses POST with a JSON body (unlike Web Search's GET + query params) to avoid// URL length limits and support richer parameters.const BRAVE_LLM_CONTEXT_ENDPOINT: &str = "https://api.search.brave.com/res/v1/llm/context";// Query and result limits (aligned with Brave API)const MAX_QUERY_LEN: usize = 400;const MAX_QUERY_WORDS: usize = 50;const MIN_COUNT: u32 = 1;const MAX_COUNT: u32 = 50;const DEFAULT_COUNT: u32 = 20;const MIN_TOKENS: u32 = 1024;const MAX_TOKENS: u32 = 32768;const DEFAULT_MAX_TOKENS: u32 = 8192;const MIN_URLS: u32 = 1;const MAX_URLS: u32 = 50;const DEFAULT_MAX_URLS: u32 = 20;const MIN_SNIPPETS: u32 = 1;const MAX_SNIPPETS: u32 = 100;const DEFAULT_MAX_SNIPPETS: u32 = 50;const MIN_TOKENS_PER_URL: u32 = 512;const MAX_TOKENS_PER_URL: u32 = 8192;const DEFAULT_MAX_TOKENS_PER_URL: u32 = 4096;const MIN_SNIPPETS_PER_URL: u32 = 1;const MAX_SNIPPETS_PER_URL: u32 = 100;const DEFAULT_SNIPPETS_PER_URL: u32 = 50;const MAX_RETRIES: u32 = 3;// Validation helpersconst VALID_THRESHOLD_MODES: [&str; 4] = ["strict", "balanced", "lenient", "disabled"];struct LlmContextTool;impl exports::near::agent::tool::Guest for LlmContextTool {    fn execute(req: exports::near::agent::tool::Request) -> exports::near::agent::tool::Response {        match execute_inner(&req.params) {            Ok(result) => exports::near::agent::tool::Response {                output: Some(result),                error: None,            },            Err(e) => exports::near::agent::tool::Response {                output: None,                error: Some(e),            },        }    }    fn schema() -> String {        SCHEMA.to_string()    }    fn description() -> String {        "Fetch pre-extracted web content from Brave Search for grounding LLM answers. \         Returns actual page content (text chunks, tables, code) relevant to the query, \         ready for RAG or fact-checking. Supports location-aware queries via optional \         loc_lat, loc_long, loc_city, loc_state, loc_country, etc. for local/POI results. \         Use when you need substantive content from the web rather than just links and \         snippets. Authentication via 'brave_api_key' (same as Web Search)."            .to_string()    }}/// Input parameters for the LLM Context API. Snake_case fields map to Brave's JSON body/// and optional X-Loc-* headers; validation happens in `validate_params`, clamping in `build_request_body`.#[derive(Debug, Default, Deserialize)]struct LlmContextParams {    #[serde(default)]    query: String,    country: Option<String>,    search_lang: Option<String>,    count: Option<u32>,    // Context Size Parameters    maximum_number_of_urls: Option<u32>,    maximum_number_of_tokens: Option<u32>,    maximum_number_of_snippets: Option<u32>,    maximum_number_of_tokens_per_url: Option<u32>,    maximum_number_of_snippets_per_url: Option<u32>,    // Filtering and Local Parameters    context_threshold_mode: Option<String>,    goggles: Option<serde_json::Value>,    // Location-aware query headers    #[serde(rename = "loc_lat")]    loc_lat: Option<f64>,    #[serde(rename = "loc_long")]    loc_long: Option<f64>,    #[serde(rename = "loc_city")]    loc_city: Option<String>,    #[serde(rename = "loc_state")]    loc_state: Option<String>,    #[serde(rename = "loc_state_name")]    loc_state_name: Option<String>,    #[serde(rename = "loc_country")]    loc_country: Option<String>,    #[serde(rename = "loc_postal_code")]    loc_postal_code: Option<String>,}/// Top-level Brave LLM Context API response: optional grounding (generic/poi/map) and optional sources map.#[derive(Debug, Deserialize)]struct BraveLlmContextResponse {    grounding: Option<Grounding>,    sources: Option<serde_json::Map<String, serde_json::Value>>,}/// Grounding content by type. See [LLM Context API](https://api-dashboard.search.brave.com/documentation/services/llm-context) and [LLM Context POST](https://api-dashboard.search.brave.com/api-reference/summarizer/llm_context/post).#[derive(Debug, Deserialize)]struct Grounding {    /// Main grounding data: array of URL objects with extracted content (text chunks, tables, code).    generic: Option<Vec<GenericEntry>>,    /// Point-of-interest data, sometimes present when local recall is enabled (e.g. via X-Loc-* headers or enable_local).    poi: Option<PoiMapEntry>,    /// Map/place results when local recall is enabled. Array of place entries with name, url, title, snippets.    map: Option<Vec<PoiMapEntry>>,}/// One URL's extracted content in `grounding.generic`: url, title, and text snippets.#[derive(Clone, Debug, Deserialize)]struct GenericEntry {    url: Option<String>,    title: Option<String>,    snippets: Option<Vec<String>>,}/// Entry shape for `grounding.poi` (single object) and `grounding.map` (array). Present when local recall is active.#[derive(Debug, Deserialize)]struct PoiMapEntry {    name: Option<String>,    url: Option<String>,    title: Option<String>,    snippets: Option<Vec<String>>,}/// Validate the input parameters against the schema.fn validate_params(params: &LlmContextParams) -> Result<(), String> {    let trimmed = params.query.trim();    if trimmed.is_empty() {        return Err("'query' must not be empty or only whitespace".into());    }    if trimmed.chars().count() > MAX_QUERY_LEN {        return Err(format!(            "'query' exceeds maximum length of {} characters",            MAX_QUERY_LEN        ));    }    let word_count = trimmed.split_whitespace().count();    if word_count > MAX_QUERY_WORDS {        return Err(format!(            "'query' exceeds maximum of {} words (got {})",            MAX_QUERY_WORDS, word_count        ));    }    // Validate optional parameters (same style as Web Search tool)    if let Some(ref lang) = params.search_lang {        if !is_valid_lang_code(lang) {            return Err(format!(                "Invalid 'search_lang': expected 2-letter code like 'en', got '{lang}'"            ));        }    }    if let Some(ref country) = params.country {        if !is_valid_country_code(country) {            return Err(format!(                "Invalid 'country': expected 2-letter code like 'US', got '{country}'"            ));        }    }    if let Some(ref mode) = params.context_threshold_mode {        if !is_valid_threshold_mode(mode) {            return Err(format!(                "Invalid 'context_threshold_mode': expected 'strict', 'balanced', 'lenient', or 'disabled', got '{mode}'"            ));        }    }    if let Some(ref goggles) = params.goggles {        if !is_valid_goggles_value(goggles) {            return Err(format!(                "Invalid 'goggles': expected a non-empty string or a non-empty array of strings (URLs or inline definitions), got '{goggles}'"            ));        }    }    if let Some(lat) = params.loc_lat {        if !(-90.0..=90.0).contains(&lat) {            return Err(format!(                "Invalid 'loc_lat': must be between -90 and 90 (got {lat})"            ));        }    }    if let Some(long) = params.loc_long {        if !(-180.0..=180.0).contains(&long) {            return Err(format!(                "Invalid 'loc_long': must be between -180 and 180 (got {long})"            ));        }    }    if let Some(ref c) = params.loc_country {        if !is_valid_country_code(c) {            return Err(format!(                "Invalid 'loc_country': expected 2-letter uppercase code like 'US', got '{c}'"            ));        }    }    Ok(())}/// Entry point: parse, validate, call API, format output.fn execute_inner(params: &str) -> Result<String, String> {    let params: LlmContextParams =        serde_json::from_str(params).map_err(|e| format!("Invalid parameters: {e}"))?;    validate_params(&params)?;    preflight_check()?;    let response_body = call_brave_api(&params)?;    let api_response: BraveLlmContextResponse = serde_json::from_str(&response_body)        .map_err(|e| format!("Failed to parse Brave response: {e}"))?;    format_output(&params.query, api_response)}/// Verify the API key is available before making the request.fn preflight_check() -> Result<(), String> {    if !near::agent::host::secret_exists("brave_api_key") {        return Err("Brave API key not found in secret store. Set it with: \             ironclaw secret set brave_api_key <key>. \             Get a key at: https://brave.com/search/api/"            .into());    }    Ok(())}/// Call the Brave LLM Context API with retry on transient server errors.////// Retries on 5xx errors only. 429 (rate limit) is not retried since the WASM/// sandbox has no sleep primitive and immediate retry would just hit the limit again.fn call_brave_api(params: &LlmContextParams) -> Result<String, String> {    let request_body = build_request_body(params)?;    let headers = build_request_headers(params);    let mut attempt = 0;    let response = loop {        attempt += 1;        let resp = near::agent::host::http_request(            "POST",            BRAVE_LLM_CONTEXT_ENDPOINT,            &headers.to_string(),            Some(&request_body),            None,        )        .map_err(|e| format!("HTTP request failed: {e}"))?;        if resp.status >= 200 && resp.status < 300 {            break resp;        }        if attempt < MAX_RETRIES && resp.status >= 500 {            near::agent::host::log(                near::agent::host::LogLevel::Warn,                &format!(                    "Brave LLM Context API error {} (attempt {}/{}). Retrying...",                    resp.status, attempt, MAX_RETRIES                ),            );            continue;        }        let error_body = String::from_utf8_lossy(&resp.body);        return Err(format!(            "Brave LLM Context API error (HTTP {}): {}",            resp.status, error_body        ));    };    String::from_utf8(response.body).map_err(|e| format!("Invalid UTF-8 response: {e}"))}/// Normalize grounding + sources into a single JSON output.fn format_output(query: &str, response: BraveLlmContextResponse) -> Result<String, String> {    let sources = response.sources.unwrap_or_default();    let grounding = response.grounding;    let generic = grounding        .as_ref()        .and_then(|g| g.generic.as_deref())        .unwrap_or_default();    let poi = grounding.as_ref().and_then(|g| g.poi.as_ref());    let map = grounding        .as_ref()        .and_then(|g| g.map.as_deref())        .unwrap_or_default();    // Count snippets from typed data before creating JSON for better performance and type safety.    let generic_snippet_count: usize = generic        .iter()        .map(|e| e.snippets.as_deref().unwrap_or_default().len())        .sum();    let poi_snippet_count: usize = poi        .map(|p| p.snippets.as_deref().unwrap_or_default().len())        .unwrap_or(0);    let map_snippet_count: usize = map        .iter()        .map(|e| e.snippets.as_deref().unwrap_or_default().len())        .sum();    let snippet_count = generic_snippet_count + poi_snippet_count + map_snippet_count;    let entries: Vec<serde_json::Value> = generic        .iter()        .filter_map(|e| {            let url = e.url.as_ref()?;            let title = e.title.as_deref().unwrap_or("Untitled");            let snippets = e.snippets.as_deref().unwrap_or(&[]);            Some(build_entry_json(url, title, None, snippets, &sources))        })        .collect();    let poi_output = poi.map(|e| poi_map_entry_to_json(e, &sources));    let map_output: Vec<serde_json::Value> = map        .iter()        .map(|e| poi_map_entry_to_json(e, &sources))        .collect();    let mut output = serde_json::json!({        "query": query,        "url_count": entries.len(),        "snippet_count": snippet_count,        "sources": entries,    });    if let Some(poi) = poi_output {        output["poi"] = poi;    }    if !map_output.is_empty() {        output["map"] = serde_json::json!(map_output);    }    serde_json::to_string(&output).map_err(|e| format!("Failed to serialize output: {e}"))}/// Build the POST request body as JSON. Clamps numeric fields to API min/max; only includes/// optional fields when present and valid.fn build_request_body(params: &LlmContextParams) -> Result<Vec<u8>, String> {    let count = params        .count        .unwrap_or(DEFAULT_COUNT)        .clamp(MIN_COUNT, MAX_COUNT);    let max_tokens = params        .maximum_number_of_tokens        .unwrap_or(DEFAULT_MAX_TOKENS)        .clamp(MIN_TOKENS, MAX_TOKENS);    let max_urls = params        .maximum_number_of_urls        .unwrap_or(DEFAULT_MAX_URLS)        .clamp(MIN_URLS, MAX_URLS);    let max_snippets = params        .maximum_number_of_snippets        .unwrap_or(DEFAULT_MAX_SNIPPETS)        .clamp(MIN_SNIPPETS, MAX_SNIPPETS);    let max_tokens_per_url = params        .maximum_number_of_tokens_per_url        .unwrap_or(DEFAULT_MAX_TOKENS_PER_URL)        .clamp(MIN_TOKENS_PER_URL, MAX_TOKENS_PER_URL);    let max_snippets_per_url = params        .maximum_number_of_snippets_per_url        .unwrap_or(DEFAULT_SNIPPETS_PER_URL)        .clamp(MIN_SNIPPETS_PER_URL, MAX_SNIPPETS_PER_URL);    let mut body = serde_json::Map::new();    body.insert(        "q".to_string(),        serde_json::Value::String(params.query.trim().to_string()),    );    // Insert number fields    let number_fields: [(&str, u32); 6] = [        ("count", count),        ("maximum_number_of_tokens", max_tokens),        ("maximum_number_of_urls", max_urls),        ("maximum_number_of_snippets", max_snippets),        ("maximum_number_of_tokens_per_url", max_tokens_per_url),        ("maximum_number_of_snippets_per_url", max_snippets_per_url),    ];    for (key, value) in number_fields {        body.insert(            key.to_string(),            serde_json::Value::Number(serde_json::Number::from(value)),        );    }    // Optional body fields:    let optional_body_strings: [(&str, Option<String>); 3] = [        ("country", params.country.clone()),        ("search_lang", params.search_lang.clone()),        (            "context_threshold_mode",            params.context_threshold_mode.clone(),        ),    ];    for (key, value) in optional_body_strings {        if let Some(v) = value {            body.insert(key.to_string(), serde_json::Value::String(v));        }    }    if let Some(goggles) = params.goggles.clone() {        body.insert("goggles".to_string(), goggles);    }    serde_json::to_vec(&serde_json::Value::Object(body))        .map_err(|e| format!("Failed to serialize request body: {e}"))}/// Build HTTP request headers: Accept, Content-Type, User-Agent, and optional X-Loc-*/// for location-aware queries. API key is injected by the host (same as Web Search).fn build_request_headers(params: &LlmContextParams) -> serde_json::Value {    let mut map = serde_json::Map::new();    map.insert(        "Accept".to_string(),        serde_json::Value::String("application/json".to_string()),    );    map.insert(        "Content-Type".to_string(),        serde_json::Value::String("application/json".to_string()),    );    map.insert(        "User-Agent".to_string(),        serde_json::Value::String("IronClaw-LlmContext-Tool/0.1".to_string()),    );    // Location-aware headers: (X-Loc-* name, optional value from params)    let loc_headers: [(&str, Option<String>); 7] = [        ("X-Loc-Lat", params.loc_lat.map(|v| v.to_string())),        ("X-Loc-Long", params.loc_long.map(|v| v.to_string())),        ("X-Loc-City", params.loc_city.clone()),        ("X-Loc-State", params.loc_state.clone()),        ("X-Loc-State-Name", params.loc_state_name.clone()),        ("X-Loc-Country", params.loc_country.clone()),        ("X-Loc-Postal-Code", params.loc_postal_code.clone()),    ];    for (header, value) in loc_headers {        if let Some(v) = value {            map.insert(header.to_string(), serde_json::Value::String(v));        }    }    serde_json::Value::Object(map)}/// Builds a JSON object for a search result entry.